// Extract blog post content from Claude response - Fixed version
try {
  // Get the input data with proper error handling
  const inputData = $input.first();

  if (!inputData || !inputData.json) {
    console.log('No input data received');
    return {
      error: 'No input data received from previous node',
      initial_blog_post: '',
      seo_metadata: '',
      full_response: ''
    };
  }

  const response = inputData.json;
  console.log('Response structure:', JSON.stringify(response, null, 2));

  // Handle different possible response structures
  let content = '';

  if (response.content && Array.isArray(response.content) && response.content[0] && response.content[0].text) {
    // Claude API format
    content = response.content[0].text;
  } else if (response.text) {
    // Simple text format
    content = response.text;
  } else if (response.response) {
    // Nested response format
    content = response.response;
  } else if (typeof response === 'string') {
    // Direct string response
    content = response;
  } else {
    console.log('Unexpected response format:', response);
    content = JSON.stringify(response);
  }

  // Extract blog post using regex
  const blogPostMatch = content.match(/<blog_post>(.*?)<\/blog_post>/s);
  const seoMetadataMatch = content.match(/<seo_metadata>(.*?)<\/seo_metadata>/s);

  let extractedBlogPost = content;
  let seoMetadata = '';

  if (blogPostMatch) {
    extractedBlogPost = blogPostMatch[1].trim();
  }

  if (seoMetadataMatch) {
    seoMetadata = seoMetadataMatch[1].trim();
  }

  // Get original parameters safely
  let originalData = {};
  try {
    const setParamsNode = $('Set Parameters').first();
    if (setParamsNode && setParamsNode.json) {
      originalData = setParamsNode.json;
    }
  } catch (error) {
    console.log('Could not get original parameters:', error.message);
  }

  return {
    initial_blog_post: extractedBlogPost,
    seo_metadata: seoMetadata,
    full_response: content,
    topic: originalData.topic || '',
    focus_keyword: originalData.focus_keyword || '',
    advanced_section: originalData.advanced_section || '',
    notes: originalData.notes || '',
    length: originalData.length || '',
    tone: originalData.tone || '',
    audience: originalData.audience || ''
  };

} catch (error) {
  console.log('Error in Extract Initial Blog Post:', error.message);
  return {
    error: error.message,
    initial_blog_post: '',
    seo_metadata: '',
    full_response: '',
    topic: '',
    focus_keyword: '',
    advanced_section: '',
    notes: '',
    length: '',
    tone: '',
    audience: ''
  };
}

// Extract review suggestions from Claude response - Fixed version
try {
  // Get the input data with proper error handling
  const inputData = $input.first();

  if (!inputData || !inputData.json) {
    console.log('No input data received in Process Review');
    return {
      error: 'No input data received from Review Blog Post node',
      review_suggestions: {},
      raw_review: ''
    };
  }

  const response = inputData.json;
  console.log('Review response structure:', JSON.stringify(response, null, 2));

  // Handle different possible response structures
  let reviewContent = '';

  if (response.content && Array.isArray(response.content) && response.content[0] && response.content[0].text) {
    // Claude API format
    reviewContent = response.content[0].text;
  } else if (response.text) {
    // Simple text format
    reviewContent = response.text;
  } else if (response.response) {
    // Nested response format
    reviewContent = response.response;
  } else if (typeof response === 'string') {
    // Direct string response
    reviewContent = response;
  } else {
    console.log('Unexpected review response format:', response);
    reviewContent = JSON.stringify(response);
  }

  // Get previous data safely
  let previousData = {};
  try {
    const extractNode = $('Extract Initial Blog Post').first();
    if (extractNode && extractNode.json) {
      previousData = extractNode.json;
    }
  } catch (error) {
    console.log('Could not get previous data from Extract Initial Blog Post:', error.message);
  }

  // Try to parse JSON from the review response
  let reviewSuggestions = {};
  try {
    // Look for JSON in the response
    const jsonMatch = reviewContent.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      reviewSuggestions = JSON.parse(jsonMatch[0]);
    } else {
      // If no JSON found, create a structured response
      reviewSuggestions = { 
        raw_review: reviewContent,
        note: 'Could not parse structured JSON from review response'
      };
    }
  } catch (error) {
    console.log('JSON parse error:', error.message);
    reviewSuggestions = { 
      raw_review: reviewContent, 
      parse_error: error.message 
    };
  }

  return {
    ...previousData,
    review_suggestions: reviewSuggestions,
    raw_review: reviewContent
  };

} catch (error) {
  console.log('Error in Process Review:', error.message);

  // Try to get previous data even if there's an error
  let fallbackData = {};
  try {
    const extractNode = $('Extract Initial Blog Post').first();
    if (extractNode && extractNode.json) {
      fallbackData = extractNode.json;
    }
  } catch (fallbackError) {
    console.log('Could not get fallback data:', fallbackError.message);
  }

  return {
    ...fallbackData,
    error: error.message,
    review_suggestions: {},
    raw_review: ''
  };
}

// Extract final blog post from Claude response - Fixed version
try {
  // Get the input data with proper error handling
  const inputData = $input.first();

  if (!inputData || !inputData.json) {
    console.log('No input data received in Extract Final Blog Post');
    return {
      success: false,
      error: 'No input data received from Final Review & Polish node',
      final_blog_post: '',
      seo_metadata: ''
    };
  }

  const response = inputData.json;
  console.log('Final response structure:', JSON.stringify(response, null, 2));

  // Handle different possible response structures
  let content = '';

  if (response.content && Array.isArray(response.content) && response.content[0] && response.content[0].text) {
    // Claude API format
    content = response.content[0].text;
  } else if (response.text) {
    // Simple text format
    content = response.text;
  } else if (response.response) {
    // Nested response format
    content = response.response;
  } else if (typeof response === 'string') {
    // Direct string response
    content = response;
  } else {
    console.log('Unexpected final response format:', response);
    content = JSON.stringify(response);
  }

  // Extract final blog post using regex
  const blogPostMatch = content.match(/<blog_post>(.*?)<\/blog_post>/s);
  const seoMetadataMatch = content.match(/<seo_metadata>(.*?)<\/seo_metadata>/s);

  let finalBlogPost = content;
  let finalSeoMetadata = '';

  if (blogPostMatch) {
    finalBlogPost = blogPostMatch[1].trim();
  }

  if (seoMetadataMatch) {
    finalSeoMetadata = seoMetadataMatch[1].trim();
  }

  // Get all previous data safely
  let previousData = {};
  try {
    const processReviewNode = $('Process Review').first();
    if (processReviewNode && processReviewNode.json) {
      previousData = processReviewNode.json;
    }
  } catch (error) {
    console.log('Could not get previous data from Process Review:', error.message);
  }

  // Calculate word count
  const wordCount = finalBlogPost.split(/\s+/).filter(word => word.length > 0).length;

  return {
    success: true,
    final_blog_post: finalBlogPost,
    seo_metadata: finalSeoMetadata,
    word_count: wordCount,
    generation_time: new Date().toISOString(),
    parameters: {
      topic: previousData.topic || '',
      focus_keyword: previousData.focus_keyword || '',
      advanced_section: previousData.advanced_section || '',
      notes: previousData.notes || '',
      length: previousData.length || '',
      tone: previousData.tone || '',
      audience: previousData.audience || ''
    },
    review_process: {
      initial_post_generated: true,
      review_completed: true,
      final_polish_completed: true,
      review_suggestions: previousData.review_suggestions || {}
    }
  };

} catch (error) {
  console.log('Error in Extract Final Blog Post:', error.message);

  // Try to get previous data even if there's an error
  let fallbackData = {};
  try {
    const processReviewNode = $('Process Review').first();
    if (processReviewNode && processReviewNode.json) {
      fallbackData = processReviewNode.json;
    }
  } catch (fallbackError) {
    console.log('Could not get fallback data:', fallbackError.message);
  }

  return {
    success: false,
    error: error.message,
    final_blog_post: '',
    seo_metadata: '',
    word_count: 0,
    generation_time: new Date().toISOString(),
    parameters: {
      topic: fallbackData.topic || '',
      focus_keyword: fallbackData.focus_keyword || '',
      advanced_section: fallbackData.advanced_section || '',
      notes: fallbackData.notes || '',
      length: fallbackData.length || '',
      tone: fallbackData.tone || '',
      audience: fallbackData.audience || ''
    },
    review_process: {
      initial_post_generated: false,
      review_completed: false,
      final_polish_completed: false,
      review_suggestions: fallbackData.review_suggestions || {}
    }
  };
}

